import (
	"fmt"
)

resp, err := client.TaxSettings().GetTaxSettings(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["tax_settings"].(map[string]any)
fmt.Println(settings["tax_rate_for_customers"], settings["prices_in_catalog"], settings["tax_message"])

